<?php
namespace App\Services; use App\Enums\WalletTransactionType; use App\Models\User; use Illuminate\Support\Facades\DB;
class WalletService { public function credit(User $user, WalletTransactionType $type, float $amount, string $description): void { DB::transaction(function() use ($user,$type,$amount,$description){ $user->increment('wallet_balance', $amount); $user->walletTransactions()->create(compact('type','amount','description')); }); } public function debit(User $user, WalletTransactionType $type, float $amount, string $description): void { DB::transaction(function() use ($user,$type,$amount,$description){ throw_if($user->wallet_balance < $amount, \DomainException::class, 'Insufficient wallet balance.'); $user->decrement('wallet_balance', $amount); $user->walletTransactions()->create(['type'=>$type,'amount'=>-$amount,'description'=>$description]); }); } }
